"use client";

import { useActionState, useState } from "react";
import { cancelMyOrder } from "@/app/actions/account";
import { keepFormOnSubmit } from "@/lib/use-keep-form";

export function CancelOrder({ orderNumber }: { orderNumber: string }) {
  const [open, setOpen] = useState(false);
  const [state, action, pending] = useActionState(cancelMyOrder, undefined);
  if (state?.ok) return <p className="animate-fade-up rounded-md bg-success/10 p-3 text-sm text-success">Order cancelled. Your refund has been initiated and will reach your account in 5–7 working days.</p>;
  if (!open) return <button onClick={() => setOpen(true)} className="btn-outline press text-sm text-danger">Cancel order</button>;
  return (
    <form action={action} onSubmit={keepFormOnSubmit(action)} className="animate-fade-up space-y-2 rounded-md border border-danger/30 bg-danger/5 p-3">
      <input type="hidden" name="orderNumber" value={orderNumber} />
      <label className="label" htmlFor="reason">Reason (optional)</label>
      <select id="reason" name="reason" className="input">
        <option value="">Select a reason</option>
        <option>Ordered by mistake</option>
        <option>Found a better price</option>
        <option>Delivery is too late</option>
        <option>Want to change items</option>
        <option>Other</option>
      </select>
      {state?.error && <p className="text-sm text-danger">{state.error}</p>}
      <div className="flex gap-2">
        <button disabled={pending} className="btn press bg-danger text-white hover:brightness-95">{pending ? "Cancelling…" : "Confirm cancellation & refund"}</button>
        <button type="button" onClick={() => setOpen(false)} className="btn-outline press">Keep order</button>
      </div>
    </form>
  );
}
